PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    MotorLatch : BOOL;
END_VAR

IF NOT EStop THEN
    MotorLatch := FALSE;
END_IF;

IF EStop OR Stop THEN
    MotorLatch := FALSE;
ELSIF Start AND NOT EStop THEN
    MotorLatch := TRUE;
END_IF;

Motor := MotorLatch;

END_PROGRAM

PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    motor_latched : BOOL;
END_VAR

IF EStop = FALSE THEN
    Motor := FALSE;
    motor_latched := FALSE;
ELSIF Stop = TRUE THEN
    Motor := FALSE;
    motor_latched := FALSE;
ELSIF Start = TRUE AND Stop = FALSE THEN
    Motor := TRUE;
    motor_latched := TRUE;
ELSE
    Motor := motor_latched;
END_IF;

END_PROGRAM

