PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    A_requested : BOOL;
    B_requested : BOOL;
END_VAR

A_requested := OpenA_Cmd;
B_requested := OpenB_Cmd;

IF NOT A_requested THEN
    DoorA := FALSE;
ELSIF NOT B_requested THEN
    DoorA := TRUE;
ELSIF A_requested AND B_requested THEN
    DoorA := TRUE;
    DoorB := FALSE;
END_IF;

IF NOT B_requested THEN
    DoorB := FALSE;
ELSIF NOT A_requested THEN
    DoorB := TRUE;
ELSIF A_requested AND B_requested THEN
    DoorA := TRUE;
    DoorB := FALSE;
END_IF;

END_PROGRAM

