END_VAR

-- Determine if each door can open based on the input commands and current states
OpenA_Allowed := OpenA_Cmd AND NOT OpenB_Cmd;
OpenB_Allowed := OpenB_Cmd AND NOT OpenA_Cmd;

-- Assign output based on allowed conditions
DoorA := OpenA_Allowed;
