PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    T_A : TON;
    T_B : TON;
END_VAR

IF OpenA_Cmd AND NOT OpenB_Cmd THEN
    T_A(IN := TRUE, PT := T#0s);
    T_B(IN := FALSE, PT := T#0s);
ELSIF OpenB_Cmd AND NOT OpenA_Cmd THEN
    T_B(IN := TRUE, PT := T#0s);
    T_A(IN := FALSE, PT := T#0s);
ELSE
    T_A(IN := FALSE, PT := T#0s);
    T_B(IN := FALSE, PT := T#0s);
END_IF;

DoorA := T_A.Q;
DoorB := T_B.Q;

END_PROGRAM

