PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    Running : BOOL;
END_VAR

// Safety conditions
IF NOT GuardClosed OR Fault THEN
    Conveyor := FALSE;
    Running := FALSE;
ELSIF StartPB AND NOT Running THEN
    Running := TRUE;
ELSIF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
END_IF;

// Latching behavior
IF Running THEN
    Conveyor := TRUE;
END_IF;

END_PROGRAM

