    NS_yellow : TON;
    NS_allred : TON;
    EW_green : TON;
    EW_yellow : TON;
    EW_allred : TON;
END_VAR

CASE State OF
    0:
        NS_green(IN := TRUE, PT := T#2s);
        NS_yellow(IN := FALSE, PT := T#0s);
        NS_allred(IN := FALSE, PT := T#0s);
        EW_green(IN := FALSE, PT := T#0s);
        EW_yellow(IN := FALSE, PT := T#0s);
        EW_allred(IN := TRUE, PT := T#1s);
    1:
        NS_green(IN := FALSE, PT := T#0s);
        NS_yellow(IN := TRUE, PT := T#1s);
        NS_allred(IN := FALSE, PT := T#0s);
        EW_green(IN := FALSE, PT := T#0s);
        EW_yellow(IN := FALSE, PT := T#0s);
        EW_allred(IN := TRUE, PT := T#0s);
    2:
        NS_green(IN := FALSE, PT := T#0s);
        NS_yellow(IN := FALSE, PT := T#0s);
        NS_allred(IN := TRUE, PT := T#1s);
        EW_green(IN := FALSE, PT := T#0s);
        EW_yellow(IN := FALSE, PT := T#0s);
        EW_allred(IN := TRUE, PT := T#0s);
    3:
        NS_green(IN := FALSE, PT := T#0s);
        NS_yellow(IN := FALSE, PT := T#0s);
        NS_allred(IN := TRUE, PT := T#0s);
        EW_green(IN := TRUE, PT := T#2s);
        EW_yellow(IN := FALSE, PT := T#0s);
        EW_allred(IN := FALSE, PT := T#0s);
    4:
        NS_green(IN := FALSE, PT := T#0s);
        NS_yellow(IN := FALSE, PT := T#0s);
        NS_allred(IN := TRUE, PT := T#0s);
        EW_green(IN := FALSE, PT := T#0s);
        EW_yellow(IN := TRUE, PT := T#1s);
        EW_allred(IN := FALSE, PT := T#0s);
    5:
        NS_green(IN := FALSE, PT := T#0s);
        NS_yellow(IN := FALSE, PT := T#0s);
        NS_allred(IN := TRUE, PT := T#0s);
        EW_green(IN := FALSE, PT := T#0s);
        EW_yellow(IN := FALSE, PT := T#0s);
        EW_allred(IN := TRUE, PT := T#1s);
END_CASE;

NS_G := NS_green.Q AND NOT NS_yellow.Q AND NOT NS_allred.Q;
NS_Y := NS_yellow.Q AND NOT NS_green.Q AND NOT NS_allred.Q;
NS_R := NS_allred.Q OR (NS_green.Q AND NS_yellow.Q);

EW_G := EW_green.Q AND NOT EW_yellow.Q AND NOT EW_allred.Q;
EW_Y := EW_yellow.Q AND NOT EW_green.Q AND NOT EW_allred.Q;
EW_R := EW_allred.Q OR (EW_green.Q AND EW_yellow.Q);

State := State + 1;
IF State > 5 THEN
    State := 0;
END_IF;
END_PROGRAM

