PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
    T1 : TON;
END_VAR

IF NOT EStop THEN
    State := 0; // Force Idle on emergency stop
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND EStop THEN
    CASE State OF
        0: // Idle
            IF Level >= LIQ_MIN THEN
                State := 1; // Transition to Fill
            END_IF;
        1: // Fill
            IF Level >= LVL_HIGH THEN
                State := 2; // Transition to Heat
            ELSE
                FillValve := TRUE;
            END_IF;
        2: // Heat
            IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
                State := 3; // Transition to React
            ELSE
                Heater := TRUE;
                Agitator := TRUE;
            END_IF;
        3: // React
            IF T1.Q THEN
                State := 4; // Transition to Drain
                T1(IN := TRUE, PT := PT_REACT);
            END_IF;
        4: // Drain
            IF Level <= LVL_LOW THEN
                State := 0; // Transition to Idle
            ELSE
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

// Ensure fill and drain valves are not both open
FillValve := FillValve AND NOT DrainValve;
DrainValve := DrainValve AND NOT FillValve;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
    T : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level > 0 AND Level < 100 THEN
    CASE State OF
        0: // Idle
            IF EStop OR Level <= 0 OR Level >= 100 THEN
                State := 0;
            ELSEIF StartBatch AND Level < LVL_HIGH THEN
                State := 1;
            END_IF;
        1: // Fill
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            IF Level >= LVL_HIGH THEN
                State := 2;
            END_IF;
        2: // Heat
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
                State := 3;
            END_IF;
        3: // React
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            T(IN := TRUE, PT := T#PT_REACTs);
            IF T.Q OR EStop THEN
                State := 4;
            END_IF;
        4: // Drain
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
