        3: // React
            IF Temp >= TEMP_SET AND NOT TON1.Q THEN
                TON1(IN := TRUE, PT := PT_REACT);
            ELSIF TON1.Q THEN
                State := 4;
            END_IF;
        4: // Drain
            IF Level <= LVL_LOW THEN
                State := 0;
            ELSE
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

// Safety conditions
FillValve := FillValve AND NOT DrainValve;
Heater := Heater AND Level >= LIQ_MIN;
