    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
END_VAR
CASE State OF
    0: -- Idle
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;

    1: -- Fill
        IF NOT EStop AND Level < LVL_HIGH AND Level >= LIQ_MIN THEN
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            IF Level >= LVL_HIGH OR NOT EStop THEN
                State := 2;
            END_IF;
        END_IF;

    2: -- Heat
        IF NOT EStop AND Level >= LIQ_MIN THEN
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            IF Temp >= TEMP_SET OR NOT EStop THEN
                State := 3;
            END_IF;
        END_IF;

    3: -- React
        IF NOT EStop AND Level >= LIQ_MIN THEN
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            IF Temp >= TEMP_SET AND NOT EStop THEN
                State := 4;
            END_IF;
        END_IF;
        IF Ticks() >= PT_REACT THEN
            State := 4;
        END_IF;

    4: -- Drain
        IF NOT EStop AND Level > LVL_LOW THEN
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            IF Level <= LVL_LOW OR NOT EStop THEN
                State := 0;
            END_IF;
        END_IF;

    ELSE
        State := 0;
END_CASE;
END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

IF NOT EStop THEN
    State := 0; // Emergency Stop -> Idle
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSE
    CASE State OF
        0: // Idle
            IF StartBatch AND Level >= LIQ_MIN THEN
                State := 1; // Transition to Fill
                FillTimer(IN := TRUE, PT := T#5s);
            END_IF;

        1: // Fill
            IF FillTimer.Q OR Level >= LVL_HIGH THEN
                State := 2; // Transition to Heat
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                FillValve := TRUE;
            END_IF;

        2: // Heat
            IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
                State := 3; // Transition to React
                Heater := TRUE;
                Agitator := TRUE;
                FillValve := FALSE;
                DrainValve := FALSE;
            END_IF;

        3: // React
            IF NOT FillTimer.Q THEN
                Heater := TRUE;
                Agitator := TRUE;
                FillValve := FALSE;
                DrainValve := FALSE;
            ELSE
                State := 4; // Transition to Drain
                Heater := FALSE;
                Agitator := FALSE;
                FillValve := FALSE;
                DrainValve := FALSE;
                DrainTimer(IN := TRUE, PT := T#3s);
            END_IF;

        4: // Drain
            IF DrainTimer.Q OR Level <= LVL_LOW THEN
                State := 0; // Transition to Idle
                Heater := FALSE;
                Agitator := FALSE;
                FillValve := FALSE;
                DrainValve := FALSE;
            ELSE
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

// Safety checks
IF FillValve AND DrainValve THEN
    State := 0; // Prevent fill and drain valves from being open together
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

IF Level < LIQ_MIN AND (Heater OR Agitator) THEN
    State := 0; // Prevent dry-firing
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

END_PROGRAM

