VAR CONSTANT
    IDLE : INT := 0;
    FILL : INT := 1;
    HEAT : INT := 2;
    REACT : INT := 3;
    DRAIN : INT := 4;
END_VAR

CASE State OF
    IDLE:
        IF StartBatch AND EStop THEN
            State := FILL;
        END_IF;
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

    FILL:
        IF NOT EStop AND Level >= LVL_HIGH AND Level >= LIQ_MIN THEN
            State := HEAT;
        END_IF;
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

    HEAT:
        IF NOT EStop AND Level >= LIQ_MIN AND Temp >= TEMP_SET THEN
            State := REACT;
        END_IF;
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

    REACT:
        IF NOT EStop AND Level >= LIQ_MIN AND Time >= PT_REACT THEN
            State := DRAIN;
        END_IF;
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

    DRAIN:
        IF NOT EStop AND Level <= LVL_LOW AND Level >= LIQ_MIN THEN
            State := IDLE;
        END_IF;
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;

    ELSE:
        State := IDLE;
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
END_CASE;

IF NOT EStop THEN
    State := IDLE;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

IF FillValve AND DrainValve OR Level < LIQ_MIN THEN
    State := IDLE;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;
END_PROGRAM

