    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR

CASE State OF
    0 : -- Idle
        IF EStop THEN
            State := 0;
        ELSIF StartCycle AND Level < 90 THEN
            State := 1;
        END_IF;
        Pump := FALSE;
        Valve := FALSE;

    1 : -- Filling
        IF EStop OR Level >= 90 THEN
            State := 0;
        ELSE
            State := 1;
        END_IF;
