    State : INT;
    OpenTimer : TON;
    CloseTimer : TON;
END_VAR

CASE State OF
    0: -- Idle
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := 2;
        END_IF;

    1: -- Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit OR Obstruction THEN
            State := 0;
        END_IF;
        OpenTimer(IN := TRUE, PT := T#5s);
        IF OpenTimer.Q THEN
            State := 0;
        END_IF;

    2: -- Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            State := 0;
        END_IF;
        CloseTimer(IN := TRUE, PT := T#5s);
        IF CloseTimer.Q THEN
            State := 0;
        END_IF;
END_CASE;
END_PROGRAM

