PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
    T1 : TON;
    T2 : TON;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND NOT StopPB THEN
                State := 1;
                T1(IN := TRUE, PT := T#2s);
                T2(IN := FALSE);
            END_IF;
        1:
            IF T1.Q THEN
                State := 2;
                T2(IN := TRUE, PT := T#2s);
            END_IF;
        2:
            IF T2.Q THEN
                State := 3;
            END_IF;
        3:
            IF StopPB OR NOT EStop THEN
                State := 0;
                T1(IN := FALSE);
                T2(IN := FALSE);
            END_IF;
    END_CASE;
ELSE
    State := 0;
    T1(IN := FALSE);
    T2(IN := FALSE);
END_IF;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE;

END_PROGRAM

