END_VAR

SeqTimer(IN := TRUE, PT := T#2s);

CASE State OF
    0:
        IF NOT EStop AND StartPB THEN
            State := 1;
        END_IF;
    1:
        C3 := TRUE;
        IF SeqTimer.Q THEN
            State := 2;
        END_IF;
    2:
        C3 := TRUE;
        C2 := TRUE;
        IF SeqTimer.Q THEN
            State := 3;
        END_IF;
    3:
        C3 := TRUE;
        C2 := TRUE;
        C1 := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

IF StopPB OR NOT EStop THEN
    State := 0;
END_IF;

END_PROGRAM

