        IF EStop = FALSE OR StartPB THEN
            SeqTimer(IN := TRUE, PT := SeqTimer_PT);
            IF SeqTimer.Q AND NOT StopPB THEN
                State := 1;
                SeqTimer(IN := FALSE);
            END_IF;
        END_IF;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        IF EStop = FALSE OR StartPB THEN
            SeqTimer(IN := TRUE, PT := SeqTimer_PT);
            IF SeqTimer.Q AND Not StopPB THEN
                State := 2;
                SeqTimer(IN := FALSE);
            END_IF;
        END_IF;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        IF EStop = FALSE OR StartPB THEN
            SeqTimer(IN := TRUE, PT := SeqTimer_PT);
            IF SeqTimer.Q AND Not StopPB THEN
                State := 3;
                SeqTimer(IN := FALSE);
            END_IF;
        END_IF;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        IF EStop = FALSE OR StartPB THEN
            SeqTimer(IN := TRUE, PT := SeqTimer_PT);
            IF SeqTimer.Q AND Not StopPB THEN
                State := 3;
                SeqTimer(IN := FALSE);
            END_IF;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
    T1 : TON;
    T2 : TON;
END_VAR

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;

    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        T1(IN := TRUE, PT := T#2s);
        IF NOT T1.Q OR EStop THEN
            State := 0;
        ELSIF T1.Q AND StartPB AND NOT EStop THEN
            State := 2;
        END_IF;

    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        T2(IN := TRUE, PT := T#2s);
        IF NOT T2.Q OR EStop THEN
            State := 0;
        ELSIF T2.Q AND StartPB AND NOT EStop THEN
            State := 3;
        END_IF;

    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    ELSE:
        State := 0;
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
END_CASE;
END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    T1 : TON;
    T2 : TON;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND NOT StopPB THEN
                State := 1;
            END_IF;
        1:
            IF T1.Q THEN
                C3 := TRUE;
                IF T2.Q THEN
                    C2 := TRUE;
                    IF StartPB AND NOT StopPB THEN
                        State := 3;
                    END_IF;
                ELSE
                    T2(IN := TRUE, PT := T#2s);
                END_IF;
            ELSE
                T1(IN := TRUE, PT := T#2s);
            END_IF;
        2:
            IF StartPB AND NOT StopPB THEN
                State := 3;
            END_IF;
        3:
            IF StopPB OR NOT StartPB THEN
                State := 0;
            END_IF;
    END_CASE;
ELSE
    State := 0;
END_IF;

C1 := State >= 3;
C2 := State >= 2;
C3 := State >= 1;
END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Done : BOOL;
END_VAR
VAR
    Count : INT;
    PrevTrigger : BOOL;
END_VAR

PrevTrigger := Trigger;

IF Reset THEN
    Count := 0;
ELSIF NOT PrevTrigger AND Trigger THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
END_IF;

Done := Count >= 3;

END_PROGRAM

